refused_program.body:
set -e

upstream_ref="{upstream_remote}/{upstream_branch}"

if ! git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  git fetch --no-tags "{upstream_remote}"
  git merge --no-commit --no-ff "$upstream_ref" || true
fi

git rev-parse -q --verify MERGE_HEAD >/dev/null

merge_head=$(git rev-parse MERGE_HEAD)
base=$(git merge-base HEAD "$merge_head")
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

build_local_additions() {
  awk -v basefile="$tmp/base" '
    function flush_hunk() {
      if (hunk_valid && hunk_oldcount == 0) {
        add[hunk_oldstart] = add[hunk_oldstart] hunk_lines
      }
      hunk_lines = ""
    }
    BEGIN {
      n = 0
      while ((getline line < basefile) > 0) { base[++n] = line }
      close(basefile)
      hunk_valid = 0
      hunk_lines = ""
    }
    /^@@ / {
      flush_hunk()
      line = $0
      sub(/^@@ -/, "", line)
      split(line, a, /[ ,]+/)
      hunk_oldstart = a[1] + 0
      if (a[2] ~ /^[0-9]+$/) hunk_oldcount = a[2] + 0
      else hunk_oldcount = 1
      hunk_valid = 1
      hunk_lines = ""
      next
    }
    {
      if (hunk_valid) {
        if ($0 ~ /^-/) {
          hunk_valid = 0
        } else if ($0 ~ /^\+/) {
          hunk_lines = hunk_lines substr($0, 2) "\n"
        }
      }
    }
    END {
      flush_hunk()
      for (i = 0; i <= n; i++) {
        if (i > 0) print base[i]
        if (i in add) printf "%s", add[i]
      }
    }
  '
}

sort_quoted_blocks() {
  awk '
    function key(line,   s) {
      s = line
      sub(/^[[:space:]]*"/, "", s)
      sub(/"?,?[[:space:]]*$/, "", s)
      return s
    }
    BEGIN { in_block=0; n=0; sortable=0 }
    {
      line=$0
      if (in_block) {
        if (line ~ /^[[:space:]]*\][[:space:]]*$/) {
          if (sortable && n > 0) {
            for (i=1;i<=n;i++) {
              for (j=i+1;j<=n;j++) {
                if (key(block[i]) > key(block[j])) {
                  t=block[i]; block[i]=block[j]; block[j]=t
                }
              }
            }
          }
          for (i=1;i<=n;i++) print block[i]
          print line
          in_block=0; n=0; sortable=0
        } else {
          if (line ~ /^[[:space:]]*".*",?[[:space:]]*$/) {
            block[++n]=line
          } else {
            block[++n]=line
            sortable=0
          }
        }
        next
      }
      if (line ~ /[[:space:]]*\[[[:space:]]*$/ && line !~ /\[\[[[:space:]]*$/) {
        print line
        in_block=1; n=0; sortable=1
        next
      }
      print line
    }
    END {
      if (in_block) { for (i=1;i<=n;i++) print block[i] }
    }
  '
}

while IFS= read -r -d '' path; do
  if git cat-file -e "$base:$path" 2>/dev/null; then
    git show "$base:$path" > "$tmp/base"
    git diff -U0 --no-color "$base" "HEAD" -- "$path" | build_local_additions > "$tmp/local_additions"
  else
    : > "$tmp/base"
    : > "$tmp/local_additions"
  fi

  if git cat-file -e "MERGE_HEAD:$path" 2>/dev/null; then
    git show "MERGE_HEAD:$path" > "$tmp/upstream"
  else
    : > "$tmp/upstream"
  fi

  git merge-file -p --union "$tmp/upstream" "$tmp/base" "$tmp/local_additions" > "$tmp/resolved" || true
  if [ ! -s "$tmp/resolved" ] && [ -s "$tmp/upstream" ]; then
    cp "$tmp/upstream" "$tmp/resolved"
  fi
  sort_quoted_blocks < "$tmp/resolved" > "$tmp/final"
  cp "$tmp/final" "$path"
  git add -- "$path"
done < <(git diff --name-only --diff-filter=U -z)

git commit --no-edit -m "Merge $upstream_ref into $(git rev-parse --abbrev-ref HEAD)" -m "Resolved conflicts by starting from upstream's version and re-adding local additions."
